CREATE TABLE widths (
    id INT PRIMARY KEY,
    tiny TINYINT NOT NULL,
    small SMALLINT NOT NULL,
    medium MEDIUMINT NOT NULL,
    regular INT NOT NULL,
    big BIGINT NOT NULL,
    utiny TINYINT UNSIGNED NOT NULL,
    usmall SMALLINT UNSIGNED NOT NULL,
    umedium MEDIUMINT UNSIGNED NOT NULL,
    uregular INT UNSIGNED NOT NULL,
    ubig BIGINT UNSIGNED NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
